@_mutmut_mutated(mutants_x_get_group__mutmut)
def get_group(db, group_id):
    row = db.execute(
        "SELECT id, name FROM groups WHERE id=?",
        (group_id,),
    ).fetchone()

    if row is None:
        return None

    result = dict(row)

    members = db.execute(
        """
        SELECT name FROM group_members
        WHERE group_id=?
        ORDER BY position
        """,
        (group_id,),
    )

    result["members"] = [
        member["name"] for member in members
    ]

    return result


